import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";

/** Status change to `done` was refused because open blockers remain. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (input.issueId === input.blockerId) {
    throw new Error(`Issue ${input.issueId} cannot block itself`);
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  const edges = await dependencyRepo.listEdges(input.orgId);
  if (createsCycle(edges, input.issueId, input.blockerId)) {
    throw new Error(
      `Linking ${input.issueId} blocked by ${input.blockerId} would create a cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issueId);
}

/** Throws `IssueBlockedError` when `issueId` still has an open blocker. */
export async function assertNotBlockedByOpenIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const blockerIds = await dependencyRepo.listOpenBlockerIds(orgId, issueId);
  if (blockerIds.length > 0) {
    throw new IssueBlockedError(blockerIds);
  }
}

/**
 * Attaches the unblocked-notification reaction. Called from
 * `registerEventHandlers()` so delivery has finished when the status or
 * archive call resolves.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offStatus = subscribe("issue.status_changed", async (payload) => {
    if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
    await notifyDependentsUnblocked(
      payload.orgId,
      payload.issueId,
      payload.actorId,
    );
  });

  const offArchive = subscribe("issue.archived", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || isClosedStatus(issue.status)) return;
    await notifyDependentsUnblocked(
      payload.orgId,
      payload.issueId,
      payload.actorId,
    );
  });

  return () => {
    offStatus();
    offArchive();
  };
}

function isClosedStatus(status: IssueStatus): boolean {
  return (CLOSED_ISSUE_STATUSES as readonly string[]).includes(status);
}

async function notifyDependentsUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const dependents = await dependencyRepo.listDependentIssues(orgId, blockerId);
  for (const issue of dependents) {
    if (issue.archivedAt !== null) continue;
    if (isClosedStatus(issue.status)) continue;
    if (issue.assigneeId === null) continue;

    const open = await dependencyRepo.listOpenBlockerIds(orgId, issue.id);
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "Issue unblocked",
      body: `"${issue.title}" is no longer blocked`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

function createsCycle(
  edges: readonly { issueId: IssueId; blockerId: IssueId }[],
  issueId: IssueId,
  blockerId: IssueId,
): boolean {
  const blockersOf = new Map<string, string[]>();
  for (const edge of edges) {
    const next = blockersOf.get(edge.issueId) ?? [];
    next.push(edge.blockerId);
    blockersOf.set(edge.issueId, next);
  }

  const seen = new Set<string>();
  const stack = [blockerId as string];
  while (stack.length > 0) {
    const current = stack.pop();
    if (current === undefined || seen.has(current)) continue;
    if (current === issueId) return true;
    seen.add(current);
    for (const next of blockersOf.get(current) ?? []) stack.push(next);
  }
  return false;
}

